実数の集合 $S$ について，$M$ が $S$ の\textbf{上限}（$\sup S$）であるとは，(i) すべての $s\in S$ で $s\le M$（$M$ は上界），(ii) $M$ より小さい数は上界でない（どんな $\varepsilon>0$ に対しても $s>M-\varepsilon$ となる $s\in S$ がある），の2つが成り立つことをいう．\textbf{下限}（$\inf S$）も不等号を逆にして同様に定める．上限・下限は $S$ に属するとは限らない．
\begin{enumerate}
\item $A=\left\{\,1-\dfrac{1}{n}\ \middle|\ n=1,2,3,\dots\right\}$ の上限と下限を求めよ．
\item $C=\left\{\,(-1)^n+\dfrac{1}{n}\ \middle|\ n=1,2,3,\dots\right\}$ の上限と下限を求めよ．
\item 有理数の集合 $B=\{\,x\in\mathbb{Q}\mid x^2<2\,\}$ の（実数の中での）上限を求めよ．
\end{enumerate}

\textbf{中間値の定理}：関数 $f$ が閉区間 $[a,b]$ で連続で $f(a)<0<f(b)$ ならば，$f(c)=0$ となる $c\in(a,b)$ が存在する．これを用いて，$f(x)=x^3+x-1$ の実数解を調べる．
\begin{enumerate}
\item 方程式 $f(x)=0$ の実数解の個数を求めよ．
\item 区間 $[0,1]$ から始めて，中点での $f$ の符号を見て解を含む半分を残す操作（\textbf{二分法}）を2回行う．残る区間を $(\alpha,\beta)$（$\alpha<\beta$）の組で答えよ．
\item 二分法を $n$ 回行ったあとの区間の幅が $10^{-3}$ 以下になる最小の $n$ を求めよ．
\end{enumerate}

次の極限を求めよ．
\begin{enumerate}
\item $\displaystyle\lim_{x\to0}\left(\frac{1}{\sin^2x}-\frac{1}{x^2}\right)$
\item $\displaystyle\lim_{x\to+0}x^{\sin x}$
\item $\displaystyle\lim_{x\to0}\frac{(1+x)^{1/x}-e}{x}$
\end{enumerate}

\textbf{平均値の定理}：$f$ が $[a,b]$ で連続，$(a,b)$ で微分可能ならば $\dfrac{f(b)-f(a)}{b-a}=f'(c)$ となる $c\in(a,b)$ が存在する．
\begin{enumerate}
\item $f(x)=x^3$，$[a,b]=[0,2]$ のとき，平均値の定理の $c$ を求めよ．
\item 平均値の定理を用いて $\displaystyle\lim_{x\to\infty}x^2\bigl(\arctan(x+1)-\arctan x\bigr)$ を求めよ．
\item $f(x)=e^x$ に対し，$h\ne0$ ごとに $e^h-1=h\,e^{\theta h}$ をみたす $\theta=\theta(h)\in(0,1)$ が定まる．$\displaystyle\lim_{h\to0}\theta(h)$ を求めよ．
\end{enumerate}

区間 $I$ 上の関数 $f$ が\textbf{一様連続}であるとは，任意の $\varepsilon>0$ に対し，ある $\delta>0$ が存在して，$x,y\in I$，$|x-y|<\delta$ ならば $|f(x)-f(y)|<\varepsilon$ が成り立つことをいう（$\delta$ は $x,y$ によらない）．
\begin{enumerate}
\item $f(x)=x^2$，$I=[0,1]$，$0<\varepsilon<1$ とする．上の条件をみたす $\delta$ の最大値（上限）を $\varepsilon$ で表せ．
\item $f(x)=\sqrt{x}$，$I=[0,\infty)$，$\varepsilon>0$ とする．上の条件をみたす $\delta$ の最大値を $\varepsilon$ で表せ．
\item $f(x)=\sin\dfrac1x$ は $I=(0,1)$ 上で連続だが一様連続でないことを示せ．
\end{enumerate}

区間 $I$ 上の関数 $f$ が\textbf{凸}であるとは，任意の $x,y\in I$，$0\le t\le1$ で $f(tx+(1-t)y)\le tf(x)+(1-t)f(y)$ が成り立つことをいう．
\begin{enumerate}
\item $f$ が $I$ で2回微分可能で $f''\ge0$ ならば $f$ は凸であることを，平均値の定理を用いて示せ．
\item 三角形の内角 $A,B,C$ について，$\sin A+\sin B+\sin C$ の最大値を求めよ．
\item $x_1,x_2,x_3,x_4>0$，$x_1+x_2+x_3+x_4=1$ のとき，$\displaystyle\sum_{i=1}^4x_i\log x_i$ の最小値を求めよ．
\end{enumerate}

\begin{enumerate}
\item 広義積分 $\displaystyle\int_2^\infty\frac{dx}{x(\log x)^2}$ の値を求めよ．
\item $q>0$ とする．級数 $\displaystyle\sum_{n=2}^\infty\frac{1}{n(\log n)^q}$ が収束する $q$ の範囲を求めよ．
\item $p>0$ とする．広義積分 $\displaystyle\int_0^\infty\frac{\sin x}{x^p}dx$ が収束する $p$ の範囲を求めよ．
\item (3) の積分が絶対収束する $p$ の範囲を求めよ．
\end{enumerate}

\begin{enumerate}
\item べき級数 $\displaystyle\sum_{n=0}^\infty\frac{(n!)^2}{(2n)!}x^n$ の収束半径を求めよ．
\item $f(x)=\displaystyle\sum_{n=1}^\infty\frac{\sin nx}{n^3}$ とする．$f$ は $\mathbb{R}$ 上の $C^1$ 級関数で $f'(x)=\displaystyle\sum_{n=1}^\infty\frac{\cos nx}{n^2}$ となることを示し，$f'(0)$ の値を求めよ．$\sum_{n\ge1}\frac1{n^2}=\frac{\pi^2}{6}$ を用いてよい．
\item $\displaystyle\int_0^\pi f(x)\,dx$ を求めよ．$\sum_{n\ge1}\frac1{n^4}=\frac{\pi^4}{90}$ を用いてよい．
\item $0\le x\le2\pi$ で $\displaystyle\sum_{n=1}^\infty\frac{\cos nx}{n^2}=\frac{\pi^2}{6}-\frac{\pi x}{2}+\frac{x^2}{4}$ が成り立つことを用いて，$f\left(\dfrac\pi2\right)$ を求めよ．
\end{enumerate}

数列 $a_n>-1$ に対し，無限積 $\prod_{n=1}^\infty(1+a_n)$ が\textbf{収束する}とは，部分積 $P_N=\prod_{n=1}^N(1+a_n)$ が $0$ でない有限の極限をもつことをいう．
\begin{enumerate}
\item $a_n\ge0$ のとき，$\prod(1+a_n)$ が収束することと $\sum a_n$ が収束することは同値であることを示せ．
\item $\displaystyle\prod_{n=2}^\infty\frac{n^3-1}{n^3+1}$ の値を求めよ．
\item $\sin\pi x=\pi x\displaystyle\prod_{n=1}^\infty\left(1-\frac{x^2}{n^2}\right)$（$x\in\mathbb{C}$ で成立）を用いて，$\displaystyle\prod_{n=1}^\infty\left(1-\frac1{4n^2}\right)$ と $\displaystyle\prod_{n=1}^\infty\left(1+\frac1{n^2}\right)$ の値を求めよ．
\end{enumerate}

2変数関数 $f(x,y)$ が $(x,y)\to(0,0)$ で極限 $L$ をもつとは，$(x,y)$ が\textbf{どんな近づき方}で $(0,0)$ に近づいても $f(x,y)$ が $L$ に近づくことをいう．特に，近づき方によって値が異なれば極限は存在しない．
\begin{enumerate}
\item $f(x,y)=\dfrac{xy}{x^2+y^2}$ について，直線 $y=2x$ に沿って $(0,0)$ に近づけたときの $f$ の極限を求めよ．
\item $g(x,y)=\dfrac{x^2y}{x^2+y^2}$ の $(x,y)\to(0,0)$ での極限を求めよ．
\item $h(x,y)=\dfrac{xy^2}{x^2+y^4}$ は，原点を通るどの直線に沿って近づけても極限は $0$ である．放物線 $x=y^2$ に沿って近づけたときの極限を求めよ．
\end{enumerate}

\begin{enumerate}
\item $f(x,y)=x^2y$，$x=\cos t$，$y=\sin t$ とする．$g(t)=f(\cos t,\sin t)$ について，連鎖律 $g'(t)=f_x\dfrac{dx}{dt}+f_y\dfrac{dy}{dt}$ を用いて $g'\left(\dfrac\pi4\right)$ を求めよ．
\item $n\ge2$ とし，$\mathbb{R}^n\setminus\{0\}$ 上で $r=\sqrt{x_1^2+\dots+x_n^2}$，$u=r^p$（$p$ は実数）とする．$\Delta u=\displaystyle\sum_{i=1}^n\frac{\partial^2u}{\partial x_i^2}=c\,r^{p-2}$ となる定数 $c$ を $p,n$ で表せ．
\item $n\ge3$ のとき，$u=r^p$ が $\mathbb{R}^n\setminus\{0\}$ で調和（$\Delta u=0$）となる $p\ne0$ を求めよ．
\end{enumerate}

$f(x,y)=e^x\sqrt{1+y}$ とする．
\begin{enumerate}
\item 曲面 $z=f(x,y)$ の点 $(0,0,1)$ における接平面を $z=ax+by+c$ の形で表したとき，右辺の式を求めよ．
\item $f$ の $(0,0)$ のまわりの2次までのテイラー多項式を求めよ．
\item (2) を用いて $f(0.1,0.2)$ の近似値を求めよ．
\end{enumerate}

$\mathbb{R}^3$ のベクトル場 $\boldsymbol{F}=(2xy+z^2,\ x^2,\ 2xz)$ を考える．
\begin{enumerate}
\item $\nabla\varphi=\boldsymbol{F}$，$\varphi(0,0,0)=0$ をみたす関数 $\varphi(x,y,z)$ を求めよ．
\item らせん $C:\ \boldsymbol{r}(t)=(\cos t,\ \sin t,\ t)$（$0\le t\le2\pi$）に沿う線積分 $\displaystyle\int_C\boldsymbol F\cdot d\boldsymbol r$ を求めよ．
\item 平面のベクトル場 $\boldsymbol G=(-y,\ x)$ について，原点中心・半径 $2$ の円を反時計回りに1周する線積分 $\displaystyle\oint\boldsymbol G\cdot d\boldsymbol r$ を求めよ．
\end{enumerate}

$f(x,y)=\dfrac{xy(x^2-y^2)}{x^2+y^2}$（$(x,y)\ne(0,0)$），$f(0,0)=0$ とする．$f_{xy}$ は $(f_x)_y$（先に $x$，次に $y$ で偏微分）を表す．
\begin{enumerate}
\item $y\ne0$ のとき $f_x(0,y)$ を $y$ で表せ．
\item $f_{xy}(0,0)$ と $f_{yx}(0,0)$ を求めよ．
\item (2) の結果がシュワルツの定理（$f_{xy},f_{yx}$ がともに連続なら $f_{xy}=f_{yx}$）と矛盾しない理由を説明せよ．
\end{enumerate}

写像 $\boldsymbol F:\mathbb{R}^2\to\mathbb{R}^2$，$\boldsymbol F(x,y)=(u,v)=(x+y^2,\ y+x^2)$ を考える．
\begin{enumerate}
\item ヤコビ行列式 $\det D\boldsymbol F(x,y)$ を求めよ．
\item $\boldsymbol F(1,1)=(2,2)$ である．$(2,2)$ の近くで定まる逆写像 $(u,v)\mapsto(x,y)$（$(2,2)\mapsto(1,1)$）について，$\dfrac{\partial x}{\partial u}$ と $\dfrac{\partial x}{\partial v}$ の $(u,v)=(2,2)$ での値を求めよ．
\item $\boldsymbol F(x,y)=(0,0)$ をみたす実数の点 $(x,y)$ の個数を求めよ．
\end{enumerate}

\begin{enumerate}
\item $p>0$ とする．広義積分 $\displaystyle\iint_{\mathbb{R}^2}\frac{dx\,dy}{(1+x^2+y^2)^p}$ が収束する $p$ の範囲を求めよ．
\item (1) の範囲で積分の値を $p$ で表せ．
\item 正方形 $D=[0,1]\times[0,1]$ 上の広義積分 $\displaystyle\iint_D\frac{dx\,dy}{1-xy}$ の値を求めよ．$\sum_{n\ge1}\frac1{n^2}=\frac{\pi^2}6$ を用いてよい．
\end{enumerate}

$a>0$ とする．
\begin{enumerate}
\item 曲面 $z=xy$ のうち $x^2+y^2\le1$ の上にある部分の面積を求めよ．
\item 球 $x^2+y^2+z^2\le a^2$ のうち円柱 $x^2+y^2\le ax$ の内部にある部分の体積を求めよ．
\item 球面 $x^2+y^2+z^2=a^2$ のうち円柱 $x^2+y^2\le ax$ の内部にある部分の面積を求めよ．
\end{enumerate}

$\boldsymbol F=(y,\ z,\ x)$ とし，$a>0$ とする．
\begin{enumerate}
\item 球面 $x^2+y^2+z^2=a^2$ と平面 $x+y+z=0$ の交わりの円 $C_1$ を，点 $(1,1,1)$ の側から見て反時計回りに1周する．$\displaystyle\oint_{C_1}\boldsymbol F\cdot d\boldsymbol r$ を求めよ．
\item 円柱 $x^2+y^2=1$ と平面 $z=2x$ の交わりの楕円 $C_2$ を，$z$ 軸の正の側から見て反時計回りに1周する．$\displaystyle\oint_{C_2}\boldsymbol F\cdot d\boldsymbol r$ を求めよ．
\item $\boldsymbol G=(-y+xz^2,\ x+e^z,\ xyz)$ とする．上半球面 $S:\ x^2+y^2+z^2=1,\ z\ge0$（外向き）について $\displaystyle\iint_S(\operatorname{rot}\boldsymbol G)\cdot\boldsymbol n\,dS$ を求めよ．
\end{enumerate}
